CREATE OR REPLACE FUNCTION private.configure_seo_reviews(p_seo_admin_id uuid,p_site_url text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE previous uuid; BEGIN IF NOT EXISTS(SELECT 1 FROM public.admin_users WHERE user_id=(SELECT auth.uid()) AND is_active=true AND archived_at IS NULL AND role='super_admin') THEN RAISE EXCEPTION 'Super-admin approval required' USING ERRCODE='42501'; END IF; IF p_seo_admin_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.admin_users WHERE id=p_seo_admin_id AND is_active=true AND archived_at IS NULL AND user_id IS NOT NULL) THEN RAISE EXCEPTION 'Select an active staff account'; END IF; IF p_site_url IS NOT NULL AND (length(p_site_url)>300 OR NOT (p_site_url ~ '^https://([a-z0-9-]+\.)*buyawarranty\.co\.uk/' OR p_site_url ~ '^sc-domain:([a-z0-9-]+\.)*buyawarranty\.co\.uk$')) THEN RAISE EXCEPTION 'Invalid Search Console property'; END IF; SELECT seo_admin_id INTO previous FROM public.seo_review_settings WHERE id=true FOR UPDATE; IF previous IS NOT NULL AND previous IS DISTINCT FROM p_seo_admin_id THEN UPDATE public.admin_users SET permissions=coalesce(permissions,'{}'::jsonb)-'tab_seo-review' WHERE id=previous; END IF; IF p_seo_admin_id IS NOT NULL THEN UPDATE public.admin_users SET permissions=coalesce(permissions,'{}'::jsonb)||jsonb_build_object('tab_seo-review',true) WHERE id=p_seo_admin_id; END IF; UPDATE public.seo_review_settings SET seo_admin_id=p_seo_admin_id,site_url=p_site_url WHERE id=true; END; $$;
DO $$ BEGIN IF public.can_review_seo(NULL) THEN RAISE EXCEPTION 'Signed-out SEO access must be denied'; END IF; BEGIN PERFORM public.decide_seo_proposal(gen_random_uuid(),'approved',''); RAISE EXCEPTION 'Signed-out approval must fail'; EXCEPTION WHEN insufficient_privilege THEN NULL; END; END; $$;